import * as THREE from './vendor/three.module.min.js';
export function createAtmosphere(scene,{reduced,getLow}){
const bursts=[],meteors=[];let time=0,nextMeteor=7,energy=0;
const spriteCanvas=document.createElement('canvas');spriteCanvas.width=spriteCanvas.height=32;const ctx=spriteCanvas.getContext('2d'),g=ctx.createRadialGradient(16,16,0,16,16,16);g.addColorStop(0,'white');g.addColorStop(.18,'#bdeeff');g.addColorStop(1,'transparent');ctx.fillStyle=g;ctx.fillRect(0,0,32,32);const texture=new THREE.CanvasTexture(spriteCanvas);
const auroraUniforms={time:{value:0},strength:{value:.5}};
const aurora=new THREE.Mesh(new THREE.PlaneGeometry(150,65,1,1),new THREE.ShaderMaterial({uniforms:auroraUniforms,vertexShader:'varying vec2 vUv; void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}',fragmentShader:`varying vec2 vUv; uniform float time; uniform float strength; void main(){float x=vUv.x;float y=vUv.y;float wave=.48+sin(x*7.0+time*.12)*.14+sin(x*17.0-time*.18)*.055;float band=exp(-pow((y-wave)*8.0,2.0));float rays=.45+.55*pow(sin(x*150.0+sin(x*20.0+time*.2)*2.0)*.5+.5,2.0);float fade=sin(x*3.14159)*smoothstep(.0,.3,y)*(1.0-smoothstep(.65,1.0,y));vec3 color=mix(vec3(.10,.68,.83),vec3(.54,.20,.82),smoothstep(.15,.85,x));gl_FragColor=vec4(color,band*rays*fade*strength);}`,transparent:true,depthWrite:false,blending:THREE.AdditiveBlending,side:THREE.DoubleSide}));aurora.position.set(0,26,-48);scene.add(aurora);
// Light shafts above the altar and a rotating celestial dial around the island.
const beam=new THREE.Mesh(new THREE.CylinderGeometry(.3,2.4,15,32,1,true),new THREE.MeshBasicMaterial({color:0x7ceaff,transparent:true,opacity:.045,depthWrite:false,side:THREE.DoubleSide,blending:THREE.AdditiveBlending}));beam.position.set(-1,10,-2);scene.add(beam);
const dial=new THREE.Group();dial.position.set(0,-.2,0);scene.add(dial);const lineMat=new THREE.LineBasicMaterial({color:0x64bddf,transparent:true,opacity:.32});for(const r of [18.4,19.3]){const pts=[];for(let i=0;i<=160;i++){const a=i/160*Math.PI*2;pts.push(new THREE.Vector3(Math.cos(a)*r,0,Math.sin(a)*r))}dial.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),lineMat))}const marks=[];for(let i=0;i<64;i++){const a=i/64*Math.PI*2;for(const r of [18.5,i%4===0?19.2:18.8])marks.push(Math.cos(a)*r,0,Math.sin(a)*r)}const markGeo=new THREE.BufferGeometry();markGeo.setAttribute('position',new THREE.Float32BufferAttribute(marks,3));dial.add(new THREE.LineSegments(markGeo,lineMat));
const fireflyPositions=new Float32Array(160*3),fireflyBase=[];for(let i=0;i<160;i++){const p=[(Math.random()-.5)*34,.4+Math.random()*8,(Math.random()-.5)*30];fireflyBase.push(p);fireflyPositions.set(p,i*3)}const fg=new THREE.BufferGeometry();fg.setAttribute('position',new THREE.BufferAttribute(fireflyPositions,3));const fireflies=new THREE.Points(fg,new THREE.PointsMaterial({map:texture,size:.24,color:0x9eecff,transparent:true,opacity:.75,blending:THREE.AdditiveBlending,depthWrite:false}));scene.add(fireflies);
const poolRings=[];for(let i=0;i<3;i++){const ring=new THREE.Mesh(new THREE.RingGeometry(1.8,1.815,70),new THREE.MeshBasicMaterial({color:0x8ceaff,transparent:true,opacity:.2,depthWrite:false,side:THREE.DoubleSide}));ring.rotation.x=-Math.PI/2;ring.position.set(10,.19+i*.002,7);scene.add(ring);poolRings.push(ring)}
function disposeBurst(b){scene.remove(b.obj);b.obj.geometry.dispose();b.obj.material.dispose()}
function burst(kind='lamp',point){if(reduced)return;energy=1;const origins={lamp:[0,2,5],bell:[-11,3,1],wish:[10,2,7],breath:[0,6,0],note:[0,5,3],mood:[0,5,3],entry:[0,6,0]};const p=point||origins[kind]||origins.lamp,n=getLow()?45:130,coords=new Float32Array(n*3),velocity=[];for(let i=0;i<n;i++){coords.set(p,i*3);const a=Math.random()*Math.PI*2,s=.6+Math.random()*3;velocity.push([Math.cos(a)*s,.7+Math.random()*3,Math.sin(a)*s])}const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.BufferAttribute(coords,3));const obj=new THREE.Points(geo,new THREE.PointsMaterial({map:texture,color:kind==='bell'?0xfca9dd:kind==='wish'?0xffce89:0x99f0ff,size:kind==='bell'?.42:.3,transparent:true,opacity:1,depthWrite:false,blending:THREE.AdditiveBlending}));scene.add(obj);bursts.push({obj,velocity,age:0});if(bursts.length>5)disposeBurst(bursts.shift())}
function meteor(){const start=new THREE.Vector3(22+Math.random()*25,30+Math.random()*10,-25-Math.random()*15);const geometry=new THREE.BufferGeometry().setFromPoints([start,start.clone().add(new THREE.Vector3(6,3,-1))]);const obj=new THREE.Line(geometry,new THREE.LineBasicMaterial({color:0xb5eaff,transparent:true,opacity:.8,blending:THREE.AdditiveBlending}));scene.add(obj);meteors.push({obj,age:0})}
return{burst,update(dt){time+=dt;energy=Math.max(0,energy-dt*.5);const low=getLow();auroraUniforms.time.value=reduced?0:time;auroraUniforms.strength.value=(low?.32:.6)+energy*.25;beam.material.opacity=.045+energy*.08;dial.rotation.y=reduced?0:time*.012;fireflies.visible=!low;const fp=fg.attributes.position;for(let i=0;i<fireflyBase.length&&!low&&!reduced;i++){const p=fireflyBase[i];fp.setXYZ(i,p[0]+Math.sin(time*.24+i)*.8,p[1]+Math.sin(time*.6+i)*.5,p[2]+Math.cos(time*.19+i)*.7)}fp.needsUpdate=!low&&!reduced;for(let i=0;i<poolRings.length;i++){const phase=reduced?i/3:(time*.13+i/3)%1;poolRings[i].scale.setScalar(.2+phase*2.9);poolRings[i].material.opacity=(1-phase)*.28}if(!reduced&&!low&&time>nextMeteor){meteor();nextMeteor=time+8+Math.random()*8}for(let i=meteors.length-1;i>=0;i--){const m=meteors[i];m.age+=dt;m.obj.position.addScaledVector(new THREE.Vector3(-13,-6,1),dt);m.obj.material.opacity=Math.max(0,1-m.age/.95);if(m.age>1){scene.remove(m.obj);m.obj.geometry.dispose();m.obj.material.dispose();meteors.splice(i,1)}}for(let i=bursts.length-1;i>=0;i--){const b=bursts[i];b.age+=dt;const a=b.obj.geometry.attributes.position;for(let k=0;k<a.count;k++){const v=b.velocity[k];a.setXYZ(k,a.getX(k)+v[0]*dt,a.getY(k)+v[1]*dt,a.getZ(k)+v[2]*dt);v[1]-=dt*.35}a.needsUpdate=true;b.obj.material.opacity=Math.max(0,1-b.age/3.2);if(b.age>3.2){disposeBurst(b);bursts.splice(i,1)}}}};
}
